    "analyzedInstructions": [
      {
        "name": "Dough Preparation",
        "steps": [
          {
            "number": 1,
            "step": "Sift the all-purpose flour into a wide mixing bowl to break up any stubborn clumps and create a light texture."
          },
          {
            "number": 2,
            "step": "Whisk the warm water together with sweet condensed milk, liquid coconut milk, and sea salt until dissolved."
          },
          {
            "number": 3,
            "step": "Crack one egg into the liquid milk mixture and beat briskly until thoroughly blended and pale yellow."
          },
          {
            "number": 4,
            "step": "Create a deep well in the middle of the sifted flour and pour in the whisked liquid mixture gradually."
          },
          {
            "number": 5,
            "step": "Stir the mixture with a sturdy wooden spoon until a shaggy dough begins to form around the bowl edges."
          },
          {
            "number": 6,
            "step": "Transfer the shaggy dough onto a clean surface and knead firmly for ten minutes until smooth and elastic."
          },
          {
            "number": 7,
            "step": "Divide the supple dough into six equal portions and shape each piece into a perfectly smooth round ball."
          },
          {
            "number": 8,
            "step": "Coat each portion generously with melted ghee to prevent drying and ensure soft layers during stretching."
          },
          {
            "number": 9,
            "step": "Place the oiled dough portions into a shallow bowl and cover tightly with plastic wrap to rest undisturbed."
          },
          {
            "number": 10,
            "step": "Let the resting dough sit at room temperature for at least ninety minutes so the gluten fully relaxes."
          }
        ]
      },
      {
        "name": "Curry Duck Filling",
        "steps": [
          {
            "number": 1,
            "step": "Finely chop the fresh shallots, garlic cloves, lemongrass stalks, and coriander roots on a wooden board."
          },
          {
            "number": 2,
            "step": "Pound the chopped aromatics in a heavy granite mortar until they form a coarse, highly fragrant paste."
          },
          {
            "number": 3,
            "step": "Heat a splash of vegetable oil in a wide skillet over medium flame until it shimmers gently."
          },
          {
            "number": 4,
            "step": "Add the pounded aromatic paste to the skillet and sauté for three minutes until deeply fragrant."
          },
          {
            "number": 5,
            "step": "Stir in yellow curry powder, ground cumin, ground coriander, and ground turmeric until well combined."
          },
          {
            "number": 6,
            "step": "Add the minced duck leg meat to the fragrant spices and cook while breaking up lumps with a spatula."
          },
          {
            "number": 7,
            "step": "Season the duck mixture with shaved palm sugar and fish sauce, stirring well over medium heat."
          },
          {
            "number": 8,
            "step": "Fold thin ribbon slices of fresh kaffir lime leaves into the skillet to infuse bright citrus notes."
          },
          {
            "number": 9,
            "step": "Continue frying the duck filling until all excess moisture evaporates and the meat turns deeply golden."
          },
          {
            "number": 10,
            "step": "Remove the seasoned filling from the heat and allow it to cool completely before assembling the flatbreads."
          }
        ]
      },
      {
        "name": "Ajat Cucumber Pickling",
        "steps": [
          {
            "number": 1,
            "step": "Pour the white vinegar, water, and granulated sugar into a small saucepan placed over medium heat."
          },
          {
            "number": 2,
            "step": "Add a pinch of salt to the pan and stir continuously until all sugar crystals dissolve completely."
          },
          {
            "number": 3,
            "step": "Bring the pickling liquid to a gentle boil, then remove it from heat to cool down to room temperature."
          },
          {
            "number": 4,
            "step": "Slice the fresh cucumber lengthwise into quarters and remove any watery core seeds with a spoon."
          },
          {
            "number": 5,
            "step": "Thinly slice the deseeded cucumbers into neat quarter-moon pieces and place them in a glass serving bowl."
          },
          {
            "number": 6,
            "step": "Thinly slice red chili peppers diagonally to create vibrant red rings for color and mild heat."
          },
          {
            "number": 7,
            "step": "Peel and thinly slice the remaining fresh shallots into delicate rings to add to the pickled salad."
          },
          {
            "number": 8,
            "step": "Toss the sliced cucumbers, red chili rings, and sliced shallots together in the glass serving bowl."
          },
          {
            "number": 9,
            "step": "Pour the cooled sweet vinegar liquid over the fresh vegetable mixture until everything is submerged."
          },
          {
            "number": 10,
            "step": "Garnish the pickled cucumber relish with fresh cilantro sprigs and set aside until serving time."
          }
        ]
      },
      {
        "name": "Assembly and Griddling",
        "steps": [
          {
            "number": 1,
            "step": "Lightly grease a large flat work surface with melted ghee to prevent the soft dough from sticking."
          },
          {
            "number": 2,
            "step": "Take one rested dough ball and press it flat using your palms to create a thick circular disc."
          },
          {
            "number": 3,
            "step": "Gently stretch and flip the dough outwards until it becomes paper-thin and nearly translucent."
          },
          {
            "number": 4,
            "step": "Crack one egg into a bowl, add a quarter of the cooled duck filling, and whisk lightly to combine."
          },
          {
            "number": 5,
            "step": "Spoon the savory duck and egg mixture onto the center of the stretched translucent dough sheet evenly."
          },
          {
            "number": 6,
            "step": "Fold the edges of the thin dough over the rich center filling to create a neat square package."
          },
          {
            "number": 7,
            "step": "Heat a tablespoon of ghee in a heavy cast-iron skillet over medium flame until shimmering hot."
          },
          {
            "number": 8,
            "step": "Carefully place the stuffed dough package into the hot skillet with seam side facing downward."
          },
          {
            "number": 9,
            "step": "Fry the flatbread for three minutes per side until crisp, golden brown, and fully cooked through."
          },
          {
            "number": 10,
            "step": "Slice the warm crispy mataba into square pieces and serve immediately alongside the chilled ajat pickle."
          }
        ]
      }
    ]
  }
]
